// BZ Companies: the Blitz provider of Enrich Contacts. Blitz keys everything on the company's
// LinkedIn page, so the pass is two calls per company: domain-to-linkedin, then employee-finder.
// One item per company out (the first call's input), or {_none:true}. The floor in Blitz's own
// six job levels (C-Team, VP, Director, Manager, Staff, Other): Staff only at small companies,
// Other always (unknown is not junior). No job_function filter: every function is asked.
const inp=$input.first().json||{};
// A domain Blitz would refuse (no dot, illegal characters) is skipped here rather than answered 422.
const okDomain=(d)=>/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/i.test(String(d||''));
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain&&okDomain(c.domain));
const LEVELS={ wide:['C-Team','VP','Director','Manager','Staff','Other'], nonjunior:['C-Team','VP','Director','Manager','Other'], manager:['C-Team','VP','Director','Manager'] };
const out=companies.map(c=>({ json:{ domain:String(c.domain).toLowerCase(), cap:Math.max(1,Math.min(50,Number(c.cap)||20)), jobLevel:LEVELS[c.floor]||LEVELS.wide, body:{ domain:'https://'+String(c.domain).toLowerCase() } } }));
if(!out.length) return [{ json:{ _none:true } }];
return out;

// BZ Roster Requests: the domain-to-linkedin answers (one per company, aligned to BZ Companies by
// index, error items included) -> one employee-finder request per company that resolved. The cap
// is max_results (1 to 50), one page: a cap never exceeds 50, so the second page is never needed.
// Companies that did not resolve, and every error, are carried in _stats for BZ Parse.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const reqs=$('BZ Companies').all().map(i=>i.json||{});
let answers=[]; try{ answers=$('BZ Domain To LinkedIn').all(); }catch(e){}
const st={ resolveCalled:0, resolved:0, unresolved:0, errors:0, noKey:0, firstError:'', failReasons:[] };
const out=[];
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req||req._none) return;
  st.resolveCalled++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.found===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='Blitz domain-to-linkedin: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||typeof b!=='object'){ st.errors++; const r='Blitz domain-to-linkedin HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const url=String(b.company_linkedin_url||'').trim();
  if(!b.found||!url){ st.unresolved++; return; }
  st.resolved++;
  out.push({ json:{ domain:req.domain, cap:req.cap, companyLinkedin:url, body:{ company_linkedin_url:url, job_level:req.jobLevel, max_results:req.cap, page:1 } } });
});
if(!out.length) return [{ json:{ _none:true, _stats:st } }];
out[0].json._stats=st;
return out;

// BZ Parse: the employee-finder answers (aligned to BZ Roster Requests by index) -> people per
// domain, plus the provider verdict in the shared provider contract (see GL Parse). Employee
// Finder returns no email, no seniority and no department per row: the title comes from the
// person's current experience at this company, seniority and department are derived from the
// title by the caller's merge. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], resolveCalled:0, resolved:0, unresolved:0, noKey:0 };
const people={};
let first={}; try{ first=$('BZ Roster Requests').first().json||{}; }catch(e){}
const rs=first._stats||{};
for(const k of ['resolveCalled','resolved','unresolved','noKey']) st[k]=Number(rs[k])||0;
st.errors+=Number(rs.errors)||0; if(rs.firstError&&!st.firstError) st.firstError=rs.firstError; for(const r of (rs.failReasons||[])) st.failReasons.push(r);
let reqs=[]; try{ reqs=$('BZ Roster Requests').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('BZ Employee Finder').all(); }catch(e){}
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.results===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='Blitz employee-finder: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||!Array.isArray(b.results)){ st.errors++; const r='Blitz employee-finder HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const list=people[req.domain]||(people[req.domain]=[]);
  for(const p of b.results){
    st.returned++;
    if(list.length>=req.cap) continue;
    const exps=Array.isArray(p.experiences)?p.experiences:[];
    const here=exps.find(e=>e&&e.job_is_current&&(norm(e.company_domain)===req.domain||String(e.company_linkedin_url||'').replace(/\/+$/,'')===req.companyLinkedin.replace(/\/+$/,'')))||exps.find(e=>e&&e.job_is_current)||exps[0]||{};
    const name=String(p.full_name||((String(p.first_name||'')+' '+String(p.last_name||'')).trim())).trim();
    if(!name) continue;
    list.push({ source:'Blitz', sourceId:String(p.linkedin_id||p.id||''), name:name, title:String(here.job_title||p.headline||'').trim(), seniority:'', department:'', email:'', linkedin:String(p.linkedin_url||'').trim(), phone:'' });
    st.kept++;
  }
});
let status='ok', reason='';
const attempted=st.resolveCalled+st.called;
if(st.noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the Blitz nodes'; }
else if(attempted&&st.errors>=attempted&&!st.kept){ status='error'; reason=st.firstError; }
else if(!attempted){ status='skipped'; reason='nothing to ask'; }
return [{ json:{ provider:'Blitz', status, reason, stats:st, people } }];

// GL Requests: the GetLeads provider of Enrich Contacts. Input: the batch plan, one item
// { companies:[{recordId, domain, company, band, cap, floor}] }. Output: one item per
// POST /api/v1/contacts/search call, or one {_none:true} when there is nothing to ask.
//
// The floor is expressed in GetLeads' own six levels (C-Team, VP, Director, Manager, Staff, Other;
// pulled live 2026-09-08). "Everyone non-junior": Staff (individual contributors) rides along
// only at small companies, Other (unknown) always rides (unknown is not junior). No department
// filter: every function is asked (ruled 2026-09-08, everyone who is not junior).
//
// One call per (floor, cap) group, sized so ONE page always holds the whole answer: domains per call =
// floor(5,000 / cap) (cap 20: 250 domains, cap 30: 166, cap 50: 100). No node pagination: proven
// 2026-09-09 (run 22643) that n8n paging on a JSON body repeats the same page and aborts with
// "identical 5x", discarding every page including the first, so the whole tier came back empty.
// Every row costs one fair-use row, never cash.
const inp=$input.first().json||{};
// A domain GetLeads would refuse (no dot, illegal characters) sinks its WHOLE call (run 22808: one
// "v12footwear" row rejected 250 domains with a 400). Such rows are skipped here and counted.
const okDomain=(d)=>/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/i.test(String(d||''));
const all=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const companies=all.filter(c=>okDomain(c.domain));
const badDomains=all.length-companies.length;
const LEVELS={ wide:['C-Team','VP','Director','Manager','Staff','Other'], nonjunior:['C-Team','VP','Director','Manager','Other'], manager:['C-Team','VP','Director','Manager'] };
const COLUMNS=['First Name','Last Name','Contact Full Name','Email','Email Verification Status','Current Job Title','Seniority Level','Department / Function','Contact LinkedIn URL','Cellphone','Direct Office Phone','Company Domain','Work Email Domain','Current Employer Name'];
const groups={};
for(const c of companies){ const floor=LEVELS[c.floor]?c.floor:'wide'; const cap=Math.max(1,Math.min(50,Number(c.cap)||20)); const k=floor+':'+String(cap).padStart(2,'0'); (groups[k]=groups[k]||{ floor, cap, list:[] }).list.push(c.domain); }
const out=[];
for(const k of Object.keys(groups).sort()){
  const g=groups[k];
  const per=Math.max(1,Math.floor(5000/g.cap));
  for(let i=0;i<g.list.length;i+=per){
    const part=g.list.slice(i,i+per);
    out.push({ json:{ body:{ domains:part, seniority:LEVELS[g.floor], max_per_company:g.cap, limit:5000, offset:0, columns:COLUMNS }, domains:part, cap:g.cap, floor:g.floor } });
  }
}
if(!out.length) return [{ json:{ _none:true, badDomains } }];
out[0].json.badDomains=badDomains;
return out;

// GL Parse: every page GetLeads answered -> people per domain, plus the provider verdict. The one
// item out is the provider contract every Enrich Contacts provider answers with:
//   { provider, status: ok | skipped | error, reason, stats:{called, returned, kept, credits, errors,
//     firstError, failReasons[]}, people:{ <domain>: [ {source, sourceId, name, title, seniority,
//     department, email, linkedin, phone} ] } }
// It never throws. A missing credential, an exhausted fair-use budget or a dead API are a status
// on this item and a line in the caller's log; the caller moves on to the next provider (ruled
// 2026-09-08: unlimited providers, nothing blocks on one of them).
//
// Rows are matched to the plan by the row's own company domain, never by call order: the node pages
// on next_offset, so one request can answer with several items and alignment by index is not
// safe. Column names in the REST answer are the catalog's raw names; the docs say display labels on
// MCP and CSV, raw names on JSON, so every field is read through a normalized-key lookup that
// accepts either spelling.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const inp=$('GL Requests').first().json||{};
const plan=$('Chunk Trigger').first().json||{};
const byDomain={}; for(const c of (Array.isArray(plan.companies)?plan.companies:[])){ if(c&&c.domain) byDomain[String(c.domain).toLowerCase()]=c; }
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], dropped:0, pages:0 };
const people={};
const norm=(d)=>String(d||'').trim().toLowerCase().replace(/^https?:\/\//,'').replace(/^www\./,'').replace(/\/.*$/,'');
const nk=(s)=>String(s).toLowerCase().replace(/[^a-z0-9]/g,'');
const pick=(row,cands)=>{ for(const c of cands){ const v=row[c]; if(v!==undefined&&v!==null&&String(v).trim()!==''&&String(v).trim()!=='N/A') return String(v).trim(); } return ''; };
const flat=(r)=>{ const o={}; for(const k of Object.keys(r||{})){ const v=r[k]; if(v&&typeof v==='object'&&!Array.isArray(v)){ for(const k2 of Object.keys(v)) o[nk(k2)]=v[k2]; } o[nk(k)]=v; } return o; };
let items=[];
if(inp._none){ return [{ json:{ provider:'GetLeads', status:'skipped', reason:'nothing to ask', stats:st, people:{} } }]; }
try{ items=$('GL Search').all(); }catch(e){ items=[]; }
let noKey=false, budget=false;
for(const it of items){
  const j=it.json||{};
  st.pages++;
  if(j.error&&j.contacts===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ noKey=true; continue; }
    if(/fair.?use|not enough credits|credits_exhausted|payment required|\b402\b/i.test(msg)){ budget=true; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
    st.errors++; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue;
  }
  if(j.ok===false||(!Array.isArray(j.contacts)&&j.message)){
    const msg=String(j.message||j.code||'answer without contacts');
    if(/fair.?use|not enough credits|credits_exhausted/i.test(msg+' '+String(j.code||''))){ budget=true; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
    st.errors++; const r='GetLeads: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue;
  }
  if(!Array.isArray(j.contacts)){ st.errors++; const r='GetLeads: unreadable answer '+JSON.stringify(j).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); continue; }
  st.credits+=Number(j.query_credits_used)||0;
  for(const raw of j.contacts){
    st.returned++;
    const r=flat(raw);
    const email=pick(r,['email','emailaddress','workemail']).toLowerCase();
    let d=norm(pick(r,['companydomain','domain','workemaildomain','emaildomain']));
    if(!d||!byDomain[d]){ const at=email.lastIndexOf('@'); const ed=at>-1?email.slice(at+1):''; if(ed&&byDomain[ed]) d=ed; }
    const c=byDomain[d];
    if(!c){ st.dropped++; continue; }
    const list=people[d]||(people[d]=[]);
    if(list.length>=(Number(c.cap)||50)) continue;
    const first=pick(r,['firstname']), last=pick(r,['lastname']);
    const name=pick(r,['contactfullname','fullname'])||((first+' '+last).trim());
    if(!name) continue;
    list.push({
      source:'GetLeads', sourceId:pick(r,['contactid','id','contactuuid','personid']),
      name:name, title:pick(r,['currentjobtitle','jobtitle','title']),
      seniority:pick(r,['senioritylevel','seniority','joblevel']), department:pick(r,['departmentfunction','jobfunction','function']),
      email:email, emailStatus:pick(r,['emailverificationstatus','emailstatus']),
      linkedin:pick(r,['contactlinkedinurl','linkedinurl','linkedin']), phone:pick(r,['cellphone','directofficephone','phone'])
    });
    st.kept++;
  }
}
try{ st.called=$('GL Requests').all().filter(i=>i.json&&!i.json._none).length; }catch(e){ st.called=st.pages; }
let status='ok', reason='';
if(noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the GetLeads node'; }
else if(budget&&!st.kept){ status='skipped'; reason='fair-use budget exhausted'; }
else if(st.errors&&!st.kept&&items.length&&st.errors>=items.length){ status='error'; reason=st.firstError; }
if(budget&&st.kept) st.failReasons.push('GetLeads: fair-use budget hit mid-batch, later pages skipped');
return [{ json:{ provider:'GetLeads', status, reason, stats:st, people } }];

// QE Companies: the QuickEnrich provider of Enrich Contacts. QuickEnrich has no seniority or
// department filter, so it is asked for everyone (ruled 2026-09-08: insert everyone, no pressure):
// one free contact-finder call per company for the roster, then one paid email search per person
// up to the cap. One item per company out (the roster request), or {_none:true}.
const inp=$input.first().json||{};
const companies=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const out=companies.map(c=>({ json:{ domain:String(c.domain).toLowerCase(), cap:Math.max(1,Math.min(50,Number(c.cap)||20)), body:{ company_url:{ include:[String(c.domain).toLowerCase()], exclude:[] }, per_page:100, page:1 } } }));
if(!out.length) return [{ json:{ _none:true } }];
return out;

// QE Pick: the roster answers (aligned to QE Companies by index) -> one email-search request per
// person, up to the cap per company, people with an email on file first. The roster is free; the
// search costs one credit only on a hit. Everyone picked is inserted, email or not: a person the
// roster named is a person, the email is the email Rootflow's problem. Errors ride in _stats.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const reqs=$('QE Companies').all().map(i=>i.json||{});
let answers=[]; try{ answers=$('QE Roster').all(); }catch(e){}
const st={ rosterCalled:0, rosterRows:0, errors:0, noKey:0, firstError:'', failReasons:[] };
const out=[]; const extra=[];
const na=(v)=>{ const s=String(v==null?'':v).trim(); return (s===''||s==='N/A')?'':s; };
answers.forEach((it,i)=>{
  const req=reqs[i]; if(!req||req._none) return;
  st.rosterCalled++;
  const j=it.json||{};
  if(j.error&&j.body===undefined&&j.data===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='QuickEnrich contact-finder: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const b=(j.body!==undefined)?j.body:j;
  const status=Number(j.statusCode)||200;
  if(status>=300||!b||typeof b!=='object'||!Array.isArray(b.data)){ st.errors++; const r='QuickEnrich contact-finder HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
  const rows=b.data.slice().sort((a,c)=>(c.has_email?1:0)-(a.has_email?1:0));
  st.rosterRows+=rows.length;
  let n=0;
  for(const p of rows){
    if(n>=req.cap) break;
    const first=na(p.first_name), last=na(p.last_name);
    if(!first) continue;
    n++;
    // Without a real LinkedIn URL the search needs company_url + first_name + last_name; a person
    // with no last name gets no search (400 otherwise, run 23568: 217 such) and is still written.
    const liRaw0=na(p.employee_linkedin); const liOk0=/^https?:\/\/([a-z0-9-]+\.)?linkedin\.com\/in\/[^\/?#\s]+/i.test(liRaw0)?liRaw0:'';
    if(!liOk0&&!last){ extra.push({ domain:req.domain, name:first, title:na(p.title), linkedin:'' }); continue; }
    // The search URL carries only the parameters that have a value: an empty linkedin_url next to
    // the name + domain trio is not a documented shape.
    // A roster LinkedIn value that is not a real linkedin.com/in/ address is not sent (QuickEnrich answers
    // 422 and the search is lost); the name + domain search runs instead (run 22643, 12 such rows).
    const liRaw=na(p.employee_linkedin); const liOk=/^https?:\/\/([a-z0-9-]+\.)?linkedin\.com\/in\/[^\/?#\s]+/i.test(liRaw)?liRaw:'';
    const q={ linkedin_url:liOk, company_url:req.domain, first_name:first, last_name:last };
    const qs=Object.keys(q).filter(k=>q[k]).map(k=>k+'='+encodeURIComponent(q[k])).join('&');
    out.push({ json:{ domain:req.domain, name:(first+' '+last).trim(), title:na(p.title), linkedin:liOk, hasEmail:!!p.has_email, hasPhone:!!p.has_phone,
      query:q, url:'https://app.quickenrich.io/api/employees/search?'+qs } });
  }
});
if(!out.length) return [{ json:{ _none:true, _stats:st, _extra:extra } }];
out[0].json._stats=st; out[0].json._extra=extra;
return out;

// QE Parse: the email-search answers (aligned to QE Pick by index) -> people per domain in the
// shared provider contract (see GL Parse). A person whose search found nothing is still a person
// (name, title, LinkedIn from the roster), written without an email. Seniority and department are
// derived from the title by the caller's merge. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], rosterCalled:0, rosterRows:0, noKey:0, emails:0 };
const people={};
let first={}; try{ first=$('QE Pick').first().json||{}; }catch(e){}
const rs=first._stats||{};
for(const k of ['rosterCalled','rosterRows','noKey']) st[k]=Number(rs[k])||0;
st.errors+=Number(rs.errors)||0; if(rs.firstError&&!st.firstError) st.firstError=rs.firstError; for(const r of (rs.failReasons||[])) st.failReasons.push(r);
let picks=[]; try{ picks=$('QE Pick').all().map(i=>i.json||{}).filter(j=>!j._none); }catch(e){}
let answers=[]; try{ answers=$('QE Email').all(); }catch(e){}
const na=(v)=>{ const s=String(v==null?'':v).trim(); return (s===''||s==='N/A')?'':s; };
answers.forEach((it,i)=>{
  const p=picks[i]; if(!p) return;
  st.called++;
  const j=it.json||{};
  let email='', phone='', sourceId='';
  if(j.error&&j.body===undefined&&j.data===undefined){
    const msg=errMsg(j.error);
    if(/credential/i.test(msg)){ st.noKey++; return; }
    st.errors++; const r='QuickEnrich email search: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r);
  } else {
    const b=(j.body!==undefined)?j.body:j;
    const status=Number(j.statusCode)||200;
    if(status>=300||!b||typeof b!=='object'){ st.errors++; const r='QuickEnrich email search HTTP '+status+' '+JSON.stringify(b).slice(0,120); if(!st.firstError) st.firstError=r; st.failReasons.push(r); }
    else { const d=(b.data&&!Array.isArray(b.data))?b.data:((Array.isArray(b.data)&&b.data[0])||{}); email=na(d.email).toLowerCase(); phone=na(d.employee_phone); if(email){ st.emails++; st.credits+=1; } }
  }
  const list=people[p.domain]||(people[p.domain]=[]);
  st.returned++;
  list.push({ source:'QuickEnrich', sourceId:sourceId, name:p.name, title:p.title, seniority:'', department:'', email:email, linkedin:p.linkedin, phone:phone });
  st.kept++;
});
// People the roster named but no search could be made for (no last name, no LinkedIn) are still people.
for(const x of (first._extra||[])){ const list=people[x.domain]||(people[x.domain]=[]); st.returned++; list.push({ source:'QuickEnrich', sourceId:'', name:x.name, title:x.title, seniority:'', department:'', email:'', linkedin:'', phone:'' }); st.kept++; }
let status='ok', reason='';
const attempted=st.rosterCalled+st.called;
if(st.noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the QuickEnrich nodes'; }
else if(attempted&&st.errors>=attempted&&!st.kept){ status='error'; reason=st.firstError; }
else if(!attempted){ status='skipped'; reason='nothing to ask'; }
return [{ json:{ provider:'QuickEnrich', status, reason, stats:st, people } }];

// Relevant Filters (Supersoniq branch): the gate's read for this chunk, one formula per 100 domains
// for the relevant People rows at the chunk's domains. Relevance is the People formula the client's
// base carries (the decision-maker rule, or manually_approved when none is set).
const inp=$('Chunk Trigger').first().json||{};
const d=Array.from(new Set((inp.companies||[]).map(c=>String(c.domain||'').toLowerCase()).filter(Boolean)));
const esc=(s)=>String(s).replace(/\\/g,'\\\\').replace(/'/g,"\\'");
const out=[];
for(let i=0;i<d.length;i+=100){ const part=d.slice(i,i+100); out.push({ json:{ formula:"AND({relevance}=1, "+(part.length===1?("{Domain}='"+esc(part[0])+"'"):('OR('+part.map(x=>"{Domain}='"+esc(x)+"'").join(',')+')'))+")" } }); }
if(!out.length) out.push({ json:{ formula:"{Domain}=''" } });
return out;

// SQ Requests: the Supersoniq provider of Enrich Contacts. Supersoniq is the one metered source
// (one credit per delivered contact, 90k a month), so it gets its own rule (ruled 2026-09-09): a
// HARD cap of 10 people per company whatever the band, and seniors only (Director and up in its
// vocabulary: Director, Head, VP, EVP / SVP, President, C-Suite, Owner, Founder, Partner,
// Board / Chair). One POST companies/enrich per 1,000 domains, tier full so the email rides.
// The gate (ruled 2026-09-09): Supersoniq is asked only for companies that still hold fewer than
// RELEVANT_MIN relevant people after the free providers wrote (Read Relevant People, this chunk).
// A base without a relevance rule has none, so every company passes; the gate counts ride in stats.
const RELEVANT_MIN=5;
const inp=$('Chunk Trigger').first().json||{};
const all=(Array.isArray(inp.companies)?inp.companies:[]).filter(c=>c&&c.domain);
const count={};
try{ for(const it of $('Read Relevant People').all()){ const j=it.json||{}; if(!j.id) continue; const f=j.fields||{}; const v=f.Domain; const d=String(Array.isArray(v)?(v[0]||''):(v||'')).toLowerCase().trim(); if(d) count[d]=(count[d]||0)+1; } }catch(e){}
const companies=all.filter(c=>(count[String(c.domain).toLowerCase()]||0)<RELEVANT_MIN);
const gate={ relevantMin:RELEVANT_MIN, companiesIn:all.length, asked:companies.length, skippedRelevant:all.length-companies.length };
const CAP=10;
const SENIORS=['Director','Head','VP','EVP / SVP','President','C-Suite','Owner','Founder','Partner','Board / Chair'];
const domains=companies.map(c=>String(c.domain).toLowerCase());
const out=[];
for(let i=0;i<domains.length;i+=1000){
  const part=domains.slice(i,i+1000);
  out.push({ json:{ body:{ companies:part.map(d=>({ domain:d })), filters:{ seniority:SENIORS }, per_company_limit:CAP, tier:'full' }, domains:part, cap:CAP } });
}
if(!out.length) return [{ json:{ _none:true, gate } }];
out[0].json.gate=gate;
return out;

// SQ Parse: companies/enrich answers (aligned to SQ Requests by index; the node never errors, a
// failure is the body) -> people per domain in the shared provider contract (see GL Parse). A
// contact at a domain we did not send is dropped; an email whose domain is neither the company
// domain nor a subdomain of it is blanked, the person kept. Out of credits is a skip, never an
// error: the caller carries on with the other providers. Never throws.
// n8n hands a node failure over as {error}: a plain string ("Credentials not found") or an object with message and description. Read both shapes.
const errMsg=(e)=>{ if(!e) return 'call failed'; if(typeof e==='string') return e; return String((e.message||'')+' '+(e.description||'')).trim()||'call failed'; };
const inp=$('SQ Requests').first().json||{};
const st={ called:0, returned:0, kept:0, credits:0, errors:0, firstError:'', failReasons:[], dropped:0, emailBlanked:0, gate:inp.gate||null };
const people={};
if(inp._none){ return [{ json:{ provider:'Supersoniq', status:'skipped', reason:'nothing to ask', stats:st, people:{} } }]; }
let reqs=[]; try{ reqs=$('SQ Requests').all().map(i=>i.json||{}); }catch(e){}
let items=[]; try{ items=$('SQ Enrich').all(); }catch(e){}
const emailDomainOk=(email,domain)=>{ const at=String(email||'').lastIndexOf('@'); if(at<0) return false; const ed=String(email).slice(at+1).toLowerCase().trim(); return ed===domain||ed.endsWith('.'+domain); };
let noKey=false, noCredits=false;
items.forEach((it,i)=>{
  const req=reqs[i]; if(!req) return;
  st.called++;
  const resp=it.json||{};
  if(resp.error&&resp.results===undefined&&(typeof resp.error==='object'||typeof resp.error==='string')){
    const msg=errMsg(resp.error);
    if(/credential/i.test(msg)){ noKey=true; return; }
    st.errors++; const r='Supersoniq: '+msg.slice(0,160); if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  if(!Array.isArray(resp.results)){
    const txt=JSON.stringify(resp).slice(0,200);
    if(/credit|balance|insufficient/i.test(txt)){ noCredits=true; const r='Supersoniq: '+txt; if(!st.firstError) st.firstError=r; st.failReasons.push(r); return; }
    if(/authentication|unauthori|api key/i.test(txt)){ noKey=true; return; }
    st.errors++; const r='Supersoniq: '+txt; if(!st.firstError) st.firstError=r; st.failReasons.push(r); return;
  }
  const cr=resp.credits_used!=null?resp.credits_used:(resp.credits!=null?resp.credits:((resp.usage&&resp.usage.credits_used)||0)); st.credits+=Number(cr)||0;
  const sent=new Set(req.domains);
  for(const r of resp.results){
    const contacts=Array.isArray(r.contacts)?r.contacts:[];
    for(const ct of contacts){
      st.returned++;
      const domain=String(ct.company_domain||'').trim().toLowerCase();
      if(!domain||!sent.has(domain)){ st.dropped++; continue; }
      const list=people[domain]||(people[domain]=[]);
      if(list.length>=req.cap) continue;
      const full=((String(ct.first_name||'')+' '+String(ct.last_name||'')).trim())||String(ct.full_name||'');
      if(!full) continue;
      let email=String(ct.email||'').trim().toLowerCase();
      if(email&&!emailDomainOk(email,domain)){ email=''; st.emailBlanked++; }
      list.push({ source:'Supersoniq', sourceId:String(ct.contact_id||ct.id||''), name:full, title:String(ct.job_title||'').trim(), seniority:String(ct.seniority||''), department:String(ct.function||''), email:email, linkedin:String(ct.linkedin_url||ct.linkedin||'').trim(), phone:'' });
      st.kept++;
    }
  }
});
let status='ok', reason='';
if(noKey&&!st.kept&&!st.errors){ status='skipped'; reason='no credential on the Supersoniq node'; }
else if(noCredits&&!st.kept){ status='skipped'; reason='out of credits'; }
else if(st.errors&&items.length&&st.errors>=items.length&&!st.kept){ status='error'; reason=st.firstError; }
return [{ json:{ provider:'Supersoniq', status, reason, stats:st, people } }];

// Writer Input: this chunk's people (from the provider's Parse node) plus the writer's contract, one
// item for Enrich Contacts Writer. The provider on the trigger says which branch ran. An empty
// answer still goes through the writer (one held read, zero written), so the counters stay honest.
const ctx=$('Chunk Trigger').first().json||{};
const PARSE={ Blitz:'BZ Parse', GetLeads:'GL Parse', QuickEnrich:'QE Parse', Supersoniq:'SQ Parse' };
let parsed={}; try{ parsed=$(PARSE[ctx.provider]).first().json||{}; }catch(e){}
return [{ json:{ base:ctx.base, peopleTableId:ctx.peopleTableId, peopleFields:ctx.peopleFields||[], contactSourceMulti:ctx.contactSourceMulti===true, dncDomains:ctx.dncDomains||[], provider:ctx.provider, companies:ctx.companies||[], people:(parsed.people&&typeof parsed.people==='object')?parsed.people:{} } }];

// Chunk Response: the last node, what the Rootflow receives: the vendor verdict (status, reason,
// stats, the Supersoniq gate counts when that branch ran) and the writer's counters. Never rows.
const ctx=$('Chunk Trigger').first().json||{};
const PARSE={ Blitz:'BZ Parse', GetLeads:'GL Parse', QuickEnrich:'QE Parse', Supersoniq:'SQ Parse' };
let p={}; try{ p=$(PARSE[ctx.provider]).first().json||{}; }catch(e){}
let w={}; try{ w=$('Call Writer').first().json||{}; }catch(e){}
const writer=(w.error&&w.written===undefined)?{ crashed:String((w.error&&w.error.message)||w.error).slice(0,160) }:w;
return [{ json:{ provider:ctx.provider, parse:{ status:p.status||'error', reason:p.reason||'', stats:p.stats||{} }, writer } }];
